mapper.select:
select *,
ST_Distance_Sphere(
            POINT(longitude, latitude),             -- 저장된 컬럼 (순서 주의: 경도, 위도)
            POINT(#{lng}, #{lat})      -- 기준 위치 (순서 주의: 경도, 위도)
        ) AS distance_in_meters
FROM attractions

    ST_Distance_Sphere(
    POINT(longitude, latitude),
    POINT(#{lng}, #{lat})
    ) <= #{m}


        AND content_type_id = #{contentType.id}


        AND (
        title LIKE CONCAT('%', #{query}, '%')
        OR
        overview LIKE CONCAT('%', #{query}, '%')
        )


ORDER BY distance_in_meters;

select count(*)
FROM attractions

    ST_Distance_Sphere(
    POINT(longitude, latitude),
    POINT(#{lng}, #{lat})
    ) <= #{m}


        AND content_type_id = #{contentType.id}


        AND (
        title LIKE CONCAT('%', #{query}, '%')
        OR
        overview LIKE CONCAT('%', #{query}, '%')
        )

;
